static constexpr uint64_t P61 = (1ULL << 61) - 1;
static inline uint64_t add61(uint64_t a, uint64_t b) { uint64_t s = a + b; return s >= P61 ? s - P61 : s; }
static inline uint64_t sub61(uint64_t a, uint64_t b) { return a >= b ? (a - b) : (a + P61 - b); }
static inline uint64_t mul61(uint64_t a, uint64_t b) {
    __uint128_t p = (__uint128_t)a * b;
    return add61((uint64_t)p & P61, (uint64_t)(p >> 61));
}
static inline uint64_t pow61(uint64_t base, uint64_t exp) {
    uint64_t r = 1;
    while (exp) { if (exp & 1) r = mul61(r, base); base = mul61(base, base); exp >>= 1; }
    return r;
}

// Polynomial ring F_{2^61-1}[x] / (x^8 - 2)
struct Poly8 { uint64_t c[8]; };

static inline Poly8 padd(const Poly8& a, const Poly8& b) {
    Poly8 r;
    for (int i = 0; i < 8; ++i) r.c[i] = add61(a.c[i], b.c[i]);
    return r;
}
static inline Poly8 psub(const Poly8& a, const Poly8& b) {
    Poly8 r;
    for (int i = 0; i < 8; ++i) r.c[i] = sub61(a.c[i], b.c[i]);
    return r;
}
static inline Poly8 pscale(const Poly8& a, uint64_t s) {
    Poly8 r;
    for (int i = 0; i < 8; ++i) r.c[i] = mul61(a.c[i], s);
    return r;
}
static inline Poly8 pmul(const Poly8& a, const Poly8& b) {
    uint64_t t[15] = {0};
    for (int i = 0; i < 8; ++i) {
        for (int j = 0; j < 8; ++j) {
            t[i + j] = add61(t[i + j], mul61(a.c[i], b.c[j]));
        }
    }
    Poly8 r;
    for (int i = 0; i < 7; ++i) r.c[i] = add61(t[i], add61(t[i + 8], t[i + 8]));
    r.c[7] = t[7];
    return r;
}

struct Op { uint8_t code; uint32_t a, b, dst; };

template<int N_DIM>
Poly8 glynn_gray_poly8(const Poly8* A) {
    constexpr int M = 1 << (N_DIM - 1);
    Poly8 row_sum[N_DIM];
    Poly8 twoA[N_DIM][N_DIM];
    for (int r = 0; r < N_DIM; ++r) {
        Poly8 s = A[r * N_DIM];
        for (int c = 1; c < N_DIM; ++c) {
            s = padd(s, A[r * N_DIM + c]);
            twoA[r][c] = padd(A[r * N_DIM + c], A[r * N_DIM + c]);
        }
        row_sum[r] = s;
    }
    Poly8 total = row_sum[0];
    for (int r = 1; r < N_DIM; ++r) total = pmul(total, row_sum[r]);
    int prev_g = 0;
    for (int step = 1; step < M; ++step) {
        int g = step ^ (step >> 1);
        int diff = g ^ prev_g;
        int col = __builtin_ctz(diff) + 1;
        if (g & diff) {
            for (int r = 0; r < N_DIM; ++r) row_sum[r] = psub(row_sum[r], twoA[r][col]);
        } else {
            for (int r = 0; r < N_DIM; ++r) row_sum[r] = padd(row_sum[r], twoA[r][col]);
        }
        Poly8 prod = row_sum[0];
        for (int r = 1; r < N_DIM; ++r) prod = pmul(prod, row_sum[r]);
        if (__builtin_parity(g)) total = psub(total, prod);
        else total = padd(total, prod);
        prev_g = g;
    }
    static const uint64_t invM = pow61(M, P61 - 2);
    return pscale(total, invM);
}


