Poly8 perm12_gen7_poly8(const Poly8* A) {
    static thread_local Poly8 w[43436];
    for (int i = 0; i < 144; ++i) w[i] = A[i];
    constexpr int K = 43291;
    for (int i = 0; i < K; ++i) {
        const Op& o = perm12_gen7_poly8_ops[i];
        if (o.code == 0) w[o.dst] = padd(w[o.a], w[o.b]);
        else if (o.code == 1) w[o.dst] = psub(w[o.a], w[o.b]);
        else w[o.dst] = pmul(w[o.a], w[o.b]);
    }
    return pscale(w[43434], 1125899906842624ULL);
}


template<int N_DIM>
void bench(Poly8 (*fn)(const Poly8*), int iters) {
    std::mt19937_64 rng(2026 + N_DIM);
    constexpr int NM = 8;
    std::vector<Poly8> mats(NM * N_DIM * N_DIM);
    for (auto& p : mats) for (int k = 0; k < 8; ++k) p.c[k] = rng() % P61;

    for (int m = 0; m < NM; ++m) {
        Poly8 r1 = glynn_gray_poly8<N_DIM>(&mats[m * N_DIM * N_DIM]);
        Poly8 r2 = fn(&mats[m * N_DIM * N_DIM]);
        for (int k = 0; k < 8; ++k) {
            if (r1.c[k] != r2.c[k]) {
                std::printf("MISMATCH n=%d mat=%d k=%d\n", N_DIM, m, k);
                std::exit(1);
            }
        }
    }

    volatile uint64_t s1 = 0, s2 = 0;
    auto t0 = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < iters; ++i)
        s1 ^= glynn_gray_poly8<N_DIM>(&mats[(i & (NM - 1)) * N_DIM * N_DIM]).c[0];
    auto t1 = std::chrono::high_resolution_clock::now();
    double us_g = std::chrono::duration<double, std::micro>(t1 - t0).count() / iters;

    auto t2 = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < iters; ++i)
        s2 ^= fn(&mats[(i & (NM - 1)) * N_DIM * N_DIM]).c[0];
    auto t3 = std::chrono::high_resolution_clock::now();
    double us_o = std::chrono::duration<double, std::micro>(t3 - t2).count() / iters;

    if (s1 != s2) std::exit(1);
    std::printf("n=%2d | Glynn+Gray: %8.2f us | Gen7 SLP: %8.2f us | Speedup: %5.2fx | BIT-EXACT (8/8)\n",
                N_DIM, us_g, us_o, us_g / us_o);
}

int main() {
    bench<4>(perm4_gen7_poly8, 5000);
    bench<5>(perm5_gen7_poly8, 2000);
    bench<6>(perm6_gen7_poly8, 1000);
    bench<7>(perm7_gen7_poly8, 500);
    bench<8>(perm8_gen7_poly8, 200);
    bench<9>(perm9_gen7_poly8, 100);
    bench<10>(perm10_gen7_poly8, 50);
    bench<11>(perm11_gen7_poly8, 25);
    bench<12>(perm12_gen7_poly8, 15);
    return 0;
}
